import{z as i,x as o,o as e,c as s,q as t,j as l,D as E,d as B,s as A,S as n}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"长训练的健康管理","description":"","frontmatter":{"title":"长训练的健康管理","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-longrun-health.md","filePath":"llm/pf2-longrun-health.md","lastUpdated":1791413859000}'),h={name:"llm/pf2-longrun-health.md"};function p(d,a,m,C,g,u){const r=o("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="长训练的健康管理" tabindex="-1">长训练的健康管理 <a class="header-anchor" href="#长训练的健康管理" aria-label="Permalink to &quot;长训练的健康管理&quot;">​</a></h1><div class="epigraph"><p>数周的训练里，损失曲线是最后知道坏消息的传感器；健康管理的对象是那些先于损失显形的信号。</p><footer>—— 据 PaLM 训练报告（Chowdhery et al., 2023）与 OPT 训练日志（Zhang et al., 2022）的尖峰处置整理</footer></div><p><a href="/llm/pf2-regularization-dropout">上一课</a>定下正则取舍，稳定件常开。本课写训练中段的健康管理：观测什么、尖峰怎么办、什么信号允许你继续跑。<a href="/llm/ti-numerical-health">观测的设施</a>——绊网分级、断言定位、注入演练——已在设施课建好；本课配的是配方口径：哪个信号指向哪一课的旋钮，以及处置后如何归档才能保住可比性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>长训练的故障谱里，损失尖峰只是显形最晚的一种。它之前还有：梯度范数漂移、update/weight 比异常、注意力 logit 抬升、低精度 amax 漂移、零更新层——<a href="/llm/num-longrun-health">低精度长跑的故障面</a>里列出的每一项都先于损失变动。没有分层观测的团队只在尖峰出现时行动，而尖峰出现时往往已经说不清是数据、优化、精度还是结构的问题。<a href="/llm/loss-curve-phases">损失曲线的分期</a>给了背景节律：压熵段、幂律段、突变段、衰减段各有正常形态；健康管理就是拿实时信号对照这张背景图，偏出节律才动手。</p><p><span class="marginnote">「update/weight 比」就是这一步权重的改动量与权重本身的比值：太小说明更新被吞了（比如掉进低精度的舍入误差里），太大说明步子迈得离谱——它常比损失尖峰早很多步亮红灯。</span></p><h3 id="尖峰的-triage" tabindex="-1">尖峰的 triage <a class="header-anchor" href="#尖峰的-triage" aria-label="Permalink to &quot;尖峰的 triage&quot;">​</a></h3><p>尖峰处置按预案走，不做现场发挥。第一步，<strong>定位</strong>：梯度范数在哪一层爆炸——全局 \\(\\ell_2\\) 范数之外要能下钻到层与张量，见<a href="/llm/ti-gradient-weight-histograms">梯度与权重直方图</a>。第二步，<strong>分因</strong>：回放可疑 batch，切数据与数值两条因果链——数据坏批与数值溢出的处置完全不同。第三步，<strong>处置</strong>：数据坏批跳过并记录；数值问题按精度链路查缩放；结构性的（注意力塌缩、\\(\\beta_2\\) 滞后导致的伪尖峰，见 <a href="/llm/adam-beta2-spikes">Adam 的 \\(\\beta_2\\) 尖峰</a>）动结构旋钮。第四步，<strong>回退或继续</strong>：权重已损则回退到最近的完整快照，见<a href="/llm/pretrain-ckpt">预训练检查点</a>的 resume 口径；处置全程留档，死线触线即杀。</p>',8)),(e(),l(n,null,{default:E(()=>[A(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%BF%A1%E5%8F%B7%E5%81%8F%E7%A6%BB%E8%8A%82%E5%BE%8B%22%5D%20--%3E%20L%5B%22%E5%AE%9A%E4%BD%8D%EF%BC%9A%E5%93%AA%E5%B1%82%E5%93%AA%E5%BC%A0%E9%87%8F%22%5D%0A%20%20L%20--%3E%20R%7B%22%E5%9B%9E%E6%94%BE%E5%88%86%E5%9B%A0%22%7D%0A%20%20R%20--%3E%7C%E6%95%B0%E6%8D%AE%E5%9D%8F%E6%89%B9%7C%20J%5B%22%E8%B7%B3%E8%BF%87%20%2B%20%E8%AE%B0%E5%BD%95%22%5D%0A%20%20R%20--%3E%7C%E6%95%B0%E5%80%BC%E9%93%BE%7C%20N%5B%22%E6%9F%A5%E7%BC%A9%E6%94%BE%E4%B8%8E%E7%B2%BE%E5%BA%A6%22%5D%0A%20%20R%20--%3E%7C%E7%BB%93%E6%9E%84%E6%80%A7%7C%20G%5B%22%E5%8A%A8%E7%BB%93%E6%9E%84%E6%97%8B%E9%92%AE%22%5D%0A%20%20J%20--%3E%20K%7B%22%E6%9D%83%E9%87%8D%E5%8F%97%E6%8D%9F%EF%BC%9F%22%7D%0A%20%20N%20--%3E%20K%0A%20%20G%20--%3E%20K%0A%20%20K%20--%3E%7C%E6%98%AF%7C%20RB%5B%22%E5%9B%9E%E9%80%80%E5%AE%8C%E6%95%B4%E5%BF%AB%E7%85%A7%22%5D%0A%20%20K%20--%3E%7C%E5%90%A6%7C%20GO%5B%22%E7%BB%A7%E7%BB%AD%20%2B%20%E5%85%A8%E7%A8%8B%E7%95%99%E6%A1%A3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配方口径三条。第一，<strong>分级响应</strong>：绊网分三级——低级断言失败即停并带定位；中级绊网触发自动快照加人工 triage；高级死线（发散、平台、吞吐塌方）启动时写明、触线即杀，响应路径不留临场决定。第二，<strong>常态巡检</strong>：update/weight 比是中心指标——向下落进 ULP 区间是吞更新，向上暴涨是尖峰前兆；告警用同周期对照带，不设绝对阈值。第三，<strong>归因纪律</strong>：尖峰不拟合进幂律段、不当噪声忽略、也不顺手压学习率了事——每一步处置写死因判据，这继承设施课「尖峰当噪声不归档」的拦错事。</p><p><span class="marginnote">梯度裁剪是保险丝不是分类器：长期步步触发说明峰值学习率没用上，或在掩盖某个结构性问题——把「靠裁剪活着」当正常状态，等于让每次真尖峰都晚一拍发现。</span></p><p><span class="marginnote">常见误区：初学者容易给巡检指标设一个写死的绝对阈值。实际上不同层、不同阶段的正常范围差得很远，该用「同周期对照带」——跟昨天同一时刻的自己比，而不是跟一个固定数比。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么信号要分层：故障的传播有先后，数值问题先于权重损坏，权重损坏先于损失可见；观测层次决定你能在一环拦截还是只能在末端救火。为什么处置要预案化：尖峰出现时人的判断质量最差——压力、时间与信息不全叠加；预案把判断前移到冷静时刻。为什么回退优于硬扛：从坏权重继续训练的隐性成本是整段轨迹被污染，之后一切对比都要加「尖峰后」脚注；回退到完整快照保住的是轨迹契约，损失的是几个小时的算力——这笔账到算力账一课再算一次。</p><p><span class="marginnote">直觉类比：发现一锅汤里掉了灰，倒掉重做一小锅，远比硬着头皮端上桌再逐桌道歉便宜——回退损失的是几小时算力，硬扛污染的是整条轨迹和之后所有对比实验的可信度。</span></p>',7)),(e(),l(n,null,{default:E(()=>[A(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E6%95%B0%E5%80%BC%E5%BC%82%E5%B8%B8%EF%BC%9Aamax%20%E6%BC%82%E7%A7%BB%20%2F%20logit%20%E6%8A%AC%E5%8D%87%22%5D%20--%3E%7C%E6%9C%80%E6%97%A9%7C%20B%5B%22%E4%BC%98%E5%8C%96%E5%BC%82%E5%B8%B8%EF%BC%9A%E6%A2%AF%E5%BA%A6%E8%8C%83%E6%95%B0%20%2F%20update-weight%20%E6%AF%94%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%9D%83%E9%87%8D%E8%A2%AB%E6%B1%A1%E6%9F%93%22%5D%0A%20%20C%20--%3E%7C%E6%9C%80%E6%99%9A%7C%20D%5B%22%E6%8D%9F%E5%A4%B1%E5%B0%96%E5%B3%B0%E5%8F%AF%E8%A7%81%22%5D%0A%20%20A%20--%3E%20E%5B%22%E6%95%B0%E5%80%BC%E5%B1%82%E6%8B%A6%E6%88%AA%EF%BC%9A%E4%BB%A3%E4%BB%B7%E6%9C%80%E5%B0%8F%22%5D%0A%20%20B%20--%3E%20F%5B%22%E4%BC%98%E5%8C%96%E5%B1%82%E6%8B%A6%E6%88%AA%EF%BC%9A%E5%BF%AB%E7%85%A7%E5%85%9C%E5%BA%95%22%5D%0A%20%20D%20--%3E%20G%5B%22%E6%9C%AB%E7%AB%AF%E6%95%91%E7%81%AB%EF%BC%9A%E5%8F%AA%E8%83%BD%E5%9B%9E%E9%80%80%E5%B9%B6%E5%8A%A0%E5%B0%96%E5%B3%B0%E5%90%8E%E8%84%9A%E6%B3%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>这张图回答的是「为什么观测要分层」：故障沿数值、优化、权重、损失四级传播，越晚发现，处置代价越大、可逆性越差。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课管训练中的配方口径，不管设施实现——绊网怎么分级、快照怎么原子发布，见<a href="/llm/ti-numerical-health">数值健康检查</a>与<a href="/llm/ti-checkpoint-engineering">检查点工程</a>。数值方案的机理（FP16 损失缩放、FP8 的 amax 统计）在<a href="/llm/pretrain-mixed-precision">混合精度</a>与低精度课程里，本课只消费它们的告警指标。中途评估的门禁是下一课：本课的信号回答「这一步有没有问题」，门禁回答「训练继续还是停下」。稳定件的机理（QK-Norm、z-loss）在正则与稳定性各课，不重复。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>损失是最后知道坏消息的传感器：梯度范数、update/weight 比、amax、logit 抬升都先于损失显形。</li><li>尖峰走四步预案：定位、回放分因、处置、回退或继续，全程留档。</li><li>绊网分级响应，死线启动时写明、触线即杀。</li><li>裁剪是保险丝不是分类器；「靠裁剪活着」说明旋钮挂错了地方。</li><li>出处：Chowdhery et al., PaLM, 2023；Zhang et al., OPT, 2022；Pascanu et al. 的梯度裁剪与尖峰来源分类。</li></ul>',5))])}const f=i(h,[["render",p]]);export{c as __pageData,f as default};
